import{_ as a,o,c as r,a6 as t}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"ローカル作業のバックアップと復元","description":"","frontmatter":{"title":"ローカル作業のバックアップと復元","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"2d6dc0f1ddc110b2a313568a12ee7ee77d4572156151d36e6a12dce4e38acf82","order":20},"headers":[],"relativePath":"ja/user/preferences/backups.md","filePath":"ja/user/preferences/backups.md","lastUpdated":1794611623000}'),d={name:"ja/user/preferences/backups.md"};function l(s,e,c,i,n,u){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="back-up-and-restore-local-work" tabindex="-1">ローカル作業のバックアップと復元 <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;ローカル作業のバックアップと復元 {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>更新、リセット、PC 移行の前に正常な構成を保存します。管理できる保存先と、TikTools を正常終了する時間が必要です。現在の UI に汎用の <strong>すべてをバックアップ</strong> ボタンはありません。個別の書き出しと、アプリを閉じたデータコピーを使います。</p><h2 id="export-reusable-definitions" tabindex="-1">再利用可能な定義を書き出す <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;再利用可能な定義を書き出す {#export-reusable-definitions}&quot;">​</a></h2><ol><li><strong>自動化</strong> で目的のプロファイルを選び、書き出しから <code>.tikprofile.json</code> を保存します。バージョンと日付を名前に含めます。</li><li>単体テンプレートは、提供されている場合にテンプレートダイアログのダウンロード・書き出しから <code>.tiktemplate.json</code> を保存します。</li><li>共有前に内容を確認します。テンプレートには送信先や設定値が含まれ得ます。プロファイル書き出しは残高、統計、実行時変数、メディア、アカウント認証情報のコピーではありません。</li></ol><h2 id="copy-the-local-data" tabindex="-1">ローカルデータをコピーする <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;ローカルデータをコピーする {#copy-the-local-data}&quot;">​</a></h2><ol><li>LIVE と共同操作の提供を止め、通常の方法で TikTools を終了します。ホストの書き込み停止を待ちます。</li><li>使用中のデータルートを特定します。既定は Windows の <code>%LOCALAPPDATA%\\TikTools</code>、Linux の <code>~/.local/share/TikTools</code>、または設定された <code>XDG_DATA_HOME</code> 配下の <code>TikTools</code> です。独自の <code>TIKTOOLS_HOME</code> やディレクトリ別上書きで場所は変わります。</li><li>ルートと、別途上書きしたデータ、プラグイン、プラグインデータ、プラグインストアのディレクトリを日付付き保存先にコピーします。<code>.db</code> 1つだけを選ばず、残っている SQLite 補助ファイルも含め、閉じた DB ディレクトリ全体をコピーします。</li><li>参照する音声ファイルは別途保管します。音声アクションは音そのものではなくパスを保持します。アプリのバージョンと独自ディレクトリの場所も記録します。</li><li>ローカル設定には非公開値が含まれ得るためコピーを保護します。Cloud 認証は OS の認証情報ストアにあり、このフォルダーコピーでは移りません。</li></ol><h2 id="restore-and-verify" tabindex="-1">復元して検証する <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;復元して検証する {#restore-and-verify}&quot;">​</a></h2><p>TikTools を閉じたまま、現在のフォルダーを別の復旧コピーとして保管します。保存ファイルを目的のパスへ戻し、互換バージョンを起動します。再接続前にプロファイル選択、残高、変数、メディアパスを確認します。可搬型の定義は自動化で書き出したプロファイル・テンプレートを取り込みます。明示的に有効化するまで定義は無効です。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;期待される結果・提供状況と対処 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>終了中のコピーと記載した入出力機能を復旧に使えますが、全バージョン間の復元を保証するものではありません。Cloud 変更は完全なバックアップではありません。復元先の版がデータを拒否したら停止し、保管したコピーに戻します。古いバイナリを再インストールしても DB 移行は戻りません。<a href="./../updates.html">更新</a> と<a href="./troubleshooting.html">トラブルシューティング</a> を参照してください。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>個別のパス指定は <code>TIKTOOLS_HOME</code> より優先されます。<code>TIKTOOLS_DATA_DIR</code> はデータベース、<code>TIKTOOLS_PLUGINS_DIR</code> はパッケージ、<code>TIKTOOLS_PLUGIN_DATA_DIR</code> はプラグイン状態、<code>TIKTOOLS_PLUGIN_STORE_DIR</code> はパッケージストアです。<code>TIKTOOLS_LOG_DIR</code> と <code>TIKTOOLS_TEMP_DIR</code> はログと一時ファイルを選びます。相対パスは起動時の作業ディレクトリ基準です。バックアップ前に <code>tiktools api call system.info --json</code> で実パスを確認し、継承した変数も記録します。ホスト停止後にデータ・パッケージ・状態と既存 WAL/SHM をコピーします。ログはデータベースの代わりになりません。</p><p><code>system.info</code> は実 home/dataDir を返します。他のディレクトリは別端末ではなくホストの実起動環境で解決します。<code>system.health</code> は集計 ready/未処理と LIVE 入口カウンターを提供します。</p>',14)])])}const f=a(d,[["render",l]]);export{h as __pageData,f as default};
